struct Locked;
struct Unlocked;
struct Door<S> { state: S }

impl Door<Locked> {
    fn unlock(self) -> Door<Unlocked> {
        Door { state: Unlocked }
    }
}

pub struct Token { _private: () }

impl Token {
    pub fn acquire() -> Option<Self> {
        Some(Token { _private: () })
    }
}
